 function runMatchesSelection(run){return run&&run.imageId===selectedImageId()&&JSON.stringify(run.sources)===JSON.stringify(sourceSpec())&&run.executionMode===executionMode()}
 async function testFirst15(){if(running)return;try{const record=recordById(selectedImageId()),sources=sourceSpec(),mode=executionMode();currentRun=newRun(record,sources,mode);await saveRun(currentRun);await executePlan(currentRun,planFor(mode,1))}catch(error){status(error?.message||error)}}
 async function continueTo105(){if(running)return;try{let run=currentRun;if(!runMatchesSelection(run)||!firstIncompleteCall(run)){const record=recordById(selectedImageId()),sources=sourceSpec(),mode=executionMode();run=newRun(record,sources,mode);await saveRun(run)}await executePlan(run,planFor(run.executionMode,BATCH_COUNT))}catch(error){status(error?.message||error)}}
 function requestStop(){if(running){stopRequested=true;status('Stop requested. The current AI call will finish, then Prompt Diagnostics will pause.')}}
 function setBusy(on){for(const id of ['promptDiagnosticsTest15','promptDiagnosticsComplete','promptDiagnosticsImage','promptDiagnosticsExecutionMode','promptDiagnosticsUseImage','promptDiagnosticsUseReactions','promptDiagnosticsUseDescription']){const el=$(id);if(el)el.disabled=Boolean(on)}const stop=$('promptDiagnosticsStop');if(stop)stop.disabled=!on;const progress=$('promptDiagnosticsProgress');if(progress&&currentRun){progress.max=expectedEvaluations(currentRun);progress.value=evaluationCount(currentRun)}renderLiveStatus(currentRun);setExportAvailability(currentRun)}
 function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
 function normalThemesHtml(run){if(!run?.normalThemes?.length)return'<span class="prompt-diagnostics-muted">No normal three-Theme result stored for this image.</span>';return run.normalThemes.map(row=>`<span class="prompt-diagnostics-normal-theme"><b>${row.slot}</b> ${escapeHtml(row.name||row.code||'Theme')} <strong>${Math.round(row.confidence*10)/10}%</strong>${row.code&&row.name?` <small>${escapeHtml(row.code)}</small>`:''}</span>`).join('')}
 function assessmentLabel(value){return String(value||'').replace(/_/g,' ').replace(/\b\w/g,m=>m.toUpperCase())}
 function definitionAnalysisHtml(row){return(row?.definitionAnalysis||[]).map(item=>`<li><div><b>[${item.part}] ${escapeHtml(assessmentLabel(item.assessment))}</b></div><div class="prompt-diagnostics-definition-part">${escapeHtml(item.text)}</div><div>${escapeHtml(item.reason)}</div></li>`).join('')}
 function groupedResults(run){const map=new Map();for(const row of run?.results||[]){const key=row.code;if(!map.has(key))map.set(key,{code:key,name:row.name,kind:row.kind,definition:row.definition,batchIndex:row.batchIndex,batchPosition:row.batchPosition,fifteen:null,five:null,three:null});const group=map.get(key);group[row.method==='three'?'three':row.method==='five'?'five':'fifteen']=row}return[...map.values()]}
 function groupConfidence(group,run){if(run.executionMode==='three')return group.three?.confidence??-1;if(run.executionMode==='five')return group.five?.confidence??-1;if(run.executionMode==='fifteen')return group.fifteen?.confidence??-1;return Math.max(group.five?.confidence??-1,group.fifteen?.confidence??-1)}
 function groupDifference(group){if(!group.five||!group.fifteen)return-1;return Math.abs(group.fifteen.confidence-group.five.confidence)}
 function orderedGroups(run){const groups=groupedResults(run),sort=$('promptDiagnosticsSort')?.value||'definition';if(sort==='confidence')groups.sort((a,b)=>groupConfidence(b,run)-groupConfidence(a,run)||a.code.localeCompare(b.code));else if(sort==='difference')groups.sort((a,b)=>groupDifference(b)-groupDifference(a)||a.code.localeCompare(b.code));else groups.sort((a,b)=>a.batchIndex-b.batchIndex||a.batchPosition-b.batchPosition);return groups}
 function evaluationHtml(row,label){if(!row)return`<section class="prompt-diagnostics-evaluation is-missing"><h5>${escapeHtml(label)}</h5><p>Not completed.</p></section>`;return`<section class="prompt-diagnostics-evaluation"><h5>${escapeHtml(label)} · <strong>${Math.round(row.confidence*10)/10}%</strong></h5><p><b>Definition-by-definition diagnosis</b></p><ol>${definitionAnalysisHtml(row)}</ol><p><b>Score reason:</b> ${escapeHtml(row.scoreReason)}</p></section>`}
 function groupSummary(group,run){if(run.executionMode==='compare'){const a=group.fifteen?.confidence,b=group.five?.confidence,d=Number.isFinite(a)&&Number.isFinite(b)?Math.round(Math.abs(a-b)*10)/10:null;return`<span>${group.kind==='prim'?'Prim':'Theme'} · ${escapeHtml(group.name)}</span><span class="prompt-diagnostics-compare-scores"><b>15:</b> ${Number.isFinite(a)?`${a}%`:'—'} <b>5:</b> ${Number.isFinite(b)?`${b}%`:'—'} ${d!=null?`<em>Δ${d}</em>`:''}</span><small>${escapeHtml(group.code)}</small>`}const row=run.executionMode==='three'?group.three:run.executionMode==='five'?group.five:group.fifteen;return`<span>${group.kind==='prim'?'Prim':'Theme'} · ${escapeHtml(group.name)}</span><strong>${row?`${Math.round(row.confidence*10)/10}%`:'—'}</strong><small>${escapeHtml(group.code)}</small>`}
 function safeFilePart(value){return String(value||'diagnostic').replace(/\.[^.]+$/,'').replace(/[^a-z0-9._-]+/gi,'-').replace(/^-+|-+$/g,'').slice(0,72)||'diagnostic'}
