 function reportCallDiagnostics(run){const rows=Object.entries(run?.callDiagnostics||{});if(!rows.length)return`<p class="note">This saved run predates site-side persistence of successful-call repair/fallback metadata. Scores, definitions, component judgments, score reasons, evidence snapshots, and any saved failures are present; exact successful focused-repair counts cannot be reconstructed after the fact.</p>`;return`<table><thead><tr><th>Call</th><th>Batch</th><th>Method</th><th>Wave</th><th>Protocol</th><th>Focused repairs</th><th>Transport retries</th></tr></thead><tbody>${rows.sort((a,b)=>String(a[0]).localeCompare(String(b[0]))).map(([key,d])=>`<tr><td>${escapeHtml(key)}</td><td>${Number(d.batchIndex)+1}</td><td>${escapeHtml(d.method)}</td><td>${Number.isInteger(d.waveIndex)?Number(d.waveIndex)+1:'—'}</td><td>${escapeHtml(d.responseProtocol||'—')}</td><td>${Number(d.focusedRepairCount)||0}</td><td>${Number(d.transportRetryCount)||0}${d.transportExhausted?' (paused)':''}</td></tr>`).join('')}</tbody></table>${rows.some(([,d])=>Array.isArray(d.focusedRepairs)&&d.focusedRepairs.length)?`<div class="repair-details">${rows.flatMap(([key,d])=>(d.focusedRepairs||[]).map(r=>`<p><b>${escapeHtml(key)} · ${escapeHtml(r.code)}</b> — strategy ${escapeHtml(r.strategy||'—')}; attempts ${Number(r.attempts)||0}; component chunk calls ${Number(r.componentChunkCalls)||0}; chunk retries ${Number(r.componentChunkRetries)||0}; final-score attempts ${Number(r.finalScoreAttempts)||0}; quality-repair attempts ${Number(r.qualityRepairAttempts)||0}${Array.isArray(r.validationIssues)&&r.validationIssues.length?`; validation: ${escapeHtml(r.validationIssues.join(" | "))}`:""}.</p>`)).join('')}</div>`:''}${rows.some(([,d])=>Array.isArray(d.transportRecoveries)&&d.transportRecoveries.length)?`<div class="repair-details">${rows.flatMap(([key,d])=>(d.transportRecoveries||[]).map(r=>`<p><b>${escapeHtml(key)} · transport attempt ${Number(r.attempt)||0}</b> — ${escapeHtml(r.errorMessage||'Failed to fetch')}${Number(r.retryDelayMs)?`; retry delay ${Math.round(Number(r.retryDelayMs)/100)/10}s`:''}.</p>`)).join('')}</div>`:''}`}
 function buildReportHtml(run){normalizeRun(run);const groups=orderedGroups(run),order=reportOrderLabel(),created=run.createdAt?new Date(run.createdAt).toLocaleString():'—',exported=new Date().toLocaleString(),completion=run.executionMode==='compare'?`${completedConceptCount(run)}/${CONCEPT_COUNT} paired concepts · ${evaluationCount(run)}/${COMPARE_EVALUATION_COUNT} evaluations`:`${completedConceptCount(run)}/${CONCEPT_COUNT} concepts`,normal=(run.normalThemes||[]).map(row=>`<tr><td>${row.slot}</td><td>${escapeHtml(row.name||'')}</td><td>${escapeHtml(row.code||'')}</td><td>${Math.round(numberOf(row.confidence)*10)/10}%</td></tr>`).join(''),summary=groups.map(g=>`<tr><td>${escapeHtml(g.code)}</td><td>${escapeHtml(g.kind==='prim'?'Prim':'Theme')}</td><td>${escapeHtml(g.name)}</td><td>${escapeHtml(reportScoreSummary(g,run))}</td></tr>`).join(''),details=groups.map(g=>{const evals=run.executionMode==='compare'?reportEvaluation(g.five,'5 × 3 result')+reportEvaluation(g.fifteen,'15-at-once result'):reportEvaluation(reportSelectedRow(g,run),modeLabel(run.executionMode));return`<article class="concept"><header><div><span class="kind">${g.kind==='prim'?'PRIM BUILDING BLOCK':'PRIMFUSION THEME'}</span><h3>${escapeHtml(g.code)} · ${escapeHtml(g.name)}</h3></div><strong class="score">${escapeHtml(reportScoreSummary(g,run))}</strong></header><h4>Current Worker definition</h4><div class="definition">${escapeHtml(g.definition)}</div>${evals}</article>`}).join(''),reactionSection=run.sources?.reactions?`<section><h2>Reaction evidence supplied</h2><table><thead><tr><th>Code</th><th>Prim</th><th>Score</th></tr></thead><tbody>${reportReactionRows(run,groups)}</tbody></table></section>`:'',descriptionSection=run.sources?.description?`<section><h2>AI Description supplied</h2><div class="description">${escapeHtml(run.description||'')}</div></section>`:'',imageSection=run.sources?.image?`<p><b>Image evidence:</b> supplied to the Worker. The saved diagnostic history stores the image identity, not a duplicate embedded image binary.</p>`:'',error=exactErrorText(run);return`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Genreactrix Prompt Diagnostics — ${escapeHtml(run.imageName)}</title><style>
 :root{font-family:Arial,Helvetica,sans-serif;color:#111;background:#fff}*{box-sizing:border-box}body{margin:0 auto;max-width:1100px;padding:28px;font-size:14px;line-height:1.45}h1,h2,h3,h4,h5{line-height:1.2}h1{margin:0 0 6px;font-size:28px}h2{margin-top:28px;border-bottom:2px solid #222;padding-bottom:5px}h3{margin:3px 0;font-size:18px}h4{margin:14px 0 7px}h5{margin:10px 0 5px}.meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px 18px;padding:12px;border:1px solid #bbb;background:#f7f7f7}.note{padding:10px;border-left:4px solid #777;background:#f6f6f6}.description,.definition{white-space:pre-wrap;padding:10px;border:1px solid #ccc;background:#fafafa}.concept{margin:20px 0;padding:14px;border:1px solid #aaa;break-inside:avoid-page}.concept>header{display:flex;justify-content:space-between;gap:15px;align-items:flex-start;border-bottom:1px solid #ccc;padding-bottom:8px}.kind{font-size:11px;font-weight:700;letter-spacing:.04em}.score{font-size:18px;white-space:nowrap}.evaluation{margin-top:12px;padding:10px;border:1px solid #ccc}.evaluation.missing{border-style:dashed}.evaluation ol{padding-left:24px}.evaluation li{margin:8px 0;padding:7px;border:1px solid #ddd;break-inside:avoid-page}.part-text{margin:3px 0;color:#333}.part-reason{margin-top:3px}.score-reason{padding-top:7px;border-top:1px solid #ddd}table{width:100%;border-collapse:collapse;margin:8px 0 18px}th,td{border:1px solid #bbb;padding:6px;text-align:left;vertical-align:top}th{background:#eee}.repair-details{font-size:12px}.footer{margin-top:32px;padding-top:10px;border-top:1px solid #aaa;font-size:11px;color:#555}@media(max-width:650px){body{padding:14px;font-size:13px}.meta{grid-template-columns:1fr}.concept>header{flex-direction:column}.score{font-size:16px}}@media print{body{max-width:none;padding:0}.concept{break-inside:auto}.concept>header,.evaluation li,table tr{break-inside:avoid}.no-print{display:none!important}@page{margin:12mm}}
 </style></head><body><header><h1>Genreactrix Prompt Diagnostics</h1><p>Fully expanded semantic diagnostic report</p></header><section class="meta"><div><b>Image:</b> ${escapeHtml(run.imageName)}</div><div><b>Image ID:</b> ${escapeHtml(run.imageId)}</div><div><b>Created:</b> ${escapeHtml(created)}</div><div><b>Exported:</b> ${escapeHtml(exported)}</div><div><b>State:</b> ${escapeHtml(String(run.state||'—'))}</div><div><b>Completion:</b> ${escapeHtml(completion)}</div><div><b>Evidence combination:</b> ${escapeHtml(run.sourceCombination)}</div><div><b>Execution mode:</b> ${escapeHtml(modeLabel(run.executionMode))}</div><div><b>Worker:</b> ${escapeHtml(run.workerVersion||'—')}</div><div><b>Matrix:</b> ${escapeHtml(run.matrixVersion||'—')}</div><div><b>Model:</b> ${escapeHtml(run.model||'—')}</div><div><b>Report order:</b> ${escapeHtml(order)}</div></section><section><h2>Normal three-Theme result</h2><table><thead><tr><th>Slot</th><th>Theme</th><th>Code</th><th>Confidence</th></tr></thead><tbody>${normal||'<tr><td colspan="4">No normal Theme result stored.</td></tr>'}</tbody></table>${imageSection}</section>${descriptionSection}${reactionSection}<section><h2>Diagnostic score index</h2><table><thead><tr><th>Code</th><th>Type</th><th>Concept</th><th>${run.executionMode==='compare'?'5×3 / 15 / Δ':'Confidence'}</th></tr></thead><tbody>${summary}</tbody></table></section><section><h2>Call / repair diagnostics</h2>${reportCallDiagnostics(run)}${error?`<h3>Saved error</h3><pre>${escapeHtml(error)}</pre>`:''}</section><section><h2>Full 78-concept reasoning</h2>${details}</section><div class="footer">Generated from the saved Genreactrix Prompt Diagnostics run. Definitions shown are the definitions stored with each diagnostic result from the Worker used for that run.</div></body></html>`}
 function exportJson(){if(!currentRun?.results?.length){status('Choose a saved diagnostic run with results first.');return}const payload={exportSchema:'genreactrix-prompt-diagnostics-export-v1',exportedAt:now(),siteBuild:window.GENREACTRIX_BUILD||null,reportOrder:reportOrderLabel(),diagnosticRun:clone(normalizeRun(currentRun))};triggerDownload(JSON.stringify(payload,null,2),'application/json;charset=utf-8',reportFilename(currentRun,'json'));status('Prompt Diagnostics JSON export created.')}
